{"operationName":"get","variables":{"id":2595},"query":"query get($id: bigint!) {
  product_counter: campaign_products_aggregate(where: {campaign_id: {_eq: $id}}) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  campaign_products: campaign_products(
    where: {campaign_id: {_eq: $id}}
    order_by: {position: asc}
  ) {
    product {
      id
      title
      color_custom_label
      size_custom_label
      enable_custom_printarea
      printareas {
        id
        name
        display_name
        width
        height
        __typename
      }
      __typename
    }
    campaign_variants_aggregate(where: {variant: {available: {_eq: true}}}) {
      aggregate {
        count
        __typename
      }
      __typename
    }
    campaign_mockups_aggregate {
      aggregate {
        count
        __typename
      }
      __typename
    }
    campaign_image_mockups_aggregate: campaign_mockups_aggregate(
      where: {type: {_eq: "image"}}
    ) {
      aggregate {
        count
        __typename
      }
      __typename
    }
    __typename
  }
  campaign_artworks: campaign_artwork_printareas(
    where: {campaign_id: {_eq: $id}, deleted_at: {_is_null: true}}
  ) {
    artwork_id
    printarea_id
    __typename
  }
  variant_counter: campaign_variants_aggregate(
    where: {campaign_product: {campaign_id: {_eq: $id}}}
  ) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  campaign_variants: campaign_variants(
    where: {campaign_product: {campaign_id: {_eq: $id}}}
  ) {
    variant_id
    variant {
      product_id
      color
      size
      price
      fulfillment_linked_id
      printarea_id
      variant_printareas {
        printarea_id
        __typename
      }
      __typename
    }
    __typename
  }
}"}

{"variables":{},"query":"{
  instances(where: {deleted_at: {_is_null: true}, visible: {_eq: true}}) {
    id
    name
    platform_domain
    platform_id
    campaign_instances_aggregate(where: {campaign_id: {_eq: 2595}}) {
      aggregate {
        count
        __typename
      }
      __typename
    }
    __typename
  }
}"}

{"operationName":"getData","variables":{"offset":0,"limit":20},"query":"query getData($offset: Int!, $limit: Int!) {
  instances_aggregate(
    where: {platform_id: {_in: [1]}, deleted_at: {_is_null: true}, visible: {_eq: true}}
    order_by: {created_at: desc}
  ) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  instances(
    offset: $offset
    limit: $limit
    where: {platform_id: {_in: [1]}, deleted_at: {_is_null: true}, visible: {_eq: true}}
    order_by: {created_at: desc}
  ) {
    id
    name
    platform_id
    campaign_instances(where: {campaign_id: {_eq: 2595}}) {
      id
      instance_id
      handle: platform_linked_handle
      need_sync
      platform_linked_id
      __typename
    }
    domain
    platform_domain
    platform {
      name
      __typename
    }
    __typename
  }
}"}

